const raw = $input.first().json;
const payload = raw.body || raw;
const isEmptyPayload = !payload || Object.keys(payload).length === 0;

// Manual test runs have no payload - default to a sample topic + URLs so the workflow is testable end to end
const triggerTopic = payload.topic || (isEmptyPayload ? 'best project management software' : null);
const triggerYourUrls = Array.isArray(payload.yourUrls) ? payload.yourUrls : (isEmptyPayload ? ['https://example.com/project-management-software'] : []);
const triggerCompetitorUrls = Array.isArray(payload.competitorUrls) ? payload.competitorUrls : (isEmptyPayload ? ['https://competitor-one.com/pm-software', 'https://competitor-two.com/pm-tools'] : []);

return [{
  json: {
    triggerTopic: triggerTopic || null,
    triggerYourUrls,
    triggerCompetitorUrls,
    results: [],
    processedTopicCount: 0
  }
}];

const item = $input.first().json;
return [{
  json: {
    ...item,
    topicQueue: [{
      topic: item.triggerTopic,
      yourUrls: (item.triggerYourUrls || []).slice(0, item.maxUrlsPerSide),
      competitorUrls: (item.triggerCompetitorUrls || []).slice(0, item.maxUrlsPerSide)
    }]
  }
}];

const state = $('Check for Ad Hoc Topic').first().json;
const response = $input.first().json;
const topics = response.topics || response.items || (Array.isArray(response) ? response : []);

const topicQueue = topics.map(t => ({
  topic: t.topic || t.name || String(t),
  yourUrls: (t.yourUrls || []).slice(0, state.maxUrlsPerSide),
  competitorUrls: (t.competitorUrls || []).slice(0, state.maxUrlsPerSide)
}));

return [{ json: { ...state, topicQueue } }];

const item = $input.first().json;
const topicQueue = [...(item.topicQueue || [])];
const next = topicQueue.shift();

return [{
  json: {
    ...item,
    topicQueue,
    currentTopic: next ? next.topic : null,
    yourUrlQueue: next ? [...next.yourUrls] : [],
    competitorUrlList: next ? [...next.competitorUrls] : [],
    hasNextTopic: !!next,
    yourSitePages: [],
    competitorEntityResults: []
  }
}];

const item = $input.first().json;
const yourUrlQueue = [...(item.yourUrlQueue || [])];
const next = yourUrlQueue.shift();

return [{
  json: {
    ...item,
    yourUrlQueue,
    currentYourUrl: next || null,
    hasNextYourUrl: !!next
  }
}];

const state = $('Get Next URL from Your Queue').first().json;
const response = $input.first().json;
const html = String(response.data || response.body || '');

function extract(re, str) {
  const m = str.match(re);
  return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}
const title = extract(/<title[^>]*>([\s\S]*?)<\/title>/i, html);

const textOnly = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    ...state,
    currentPageTitle: title,
    currentPageText: textOnly.slice(0, 4000)
  }
}];

const item = $input.first().json;
return [{
  json: {
    ...item,
    yourSitePages: [...(item.yourSitePages || []), { url: item.currentYourUrl, title: item.currentPageTitle, text: item.currentPageText }]
  }
}];

const aiResponse = $input.first().json;
const state = $('Check Your URL Queue Status').first().json;

let parsed;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { entities: [] };
}

const yourEntities = (parsed.entities || []).map(e => ({
  ...e,
  normalizedName: (e.name || '').trim().toLowerCase()
}));

return [{
  json: {
    ...state,
    yourEntities
  }
}];

const item = $input.first().json;
const competitorQueue = (item.competitorUrlList || []).map(c => {
  if (typeof c === 'string') {
    let name = c;
    try { name = new URL(c).host; } catch (e) { /* keep raw string as name */ }
    return { competitorName: name, url: c };
  }
  return { competitorName: c.competitorName || c.name || c.url, url: c.url };
});

return [{
  json: {
    ...item,
    competitorQueue
  }
}];

const item = $input.first().json;
const competitorQueue = [...(item.competitorQueue || [])];
const next = competitorQueue.shift();

return [{
  json: {
    ...item,
    competitorQueue,
    currentCompetitorName: next ? next.competitorName : null,
    currentCompetitorUrl: next ? next.url : null,
    hasNextCompetitorUrl: !!next
  }
}];

const state = $('Retrieve next Competitor URL').first().json;
const response = $input.first().json;
const html = String(response.data || response.body || '');

function extract(re, str) {
  const m = str.match(re);
  return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}
const title = extract(/<title[^>]*>([\s\S]*?)<\/title>/i, html);

const textOnly = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    ...state,
    currentCompetitorPageTitle: title,
    currentCompetitorPageText: textOnly.slice(0, 4000)
  }
}];

const aiResponse = $input.first().json;
const state = $('Parse Competitor Page Content').first().json;

let parsed;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { entities: [] };
}

const entities = (parsed.entities || []).map(e => ({
  ...e,
  normalizedName: (e.name || '').trim().toLowerCase()
}));

return [{
  json: {
    ...state,
    competitorEntityResults: [...(state.competitorEntityResults || []), {
      competitorName: state.currentCompetitorName,
      url: state.currentCompetitorUrl,
      entities
    }]
  }
}];

const state = $('Check Competitor Queue Status').first().json;
const results = state.competitorEntityResults || [];

const entityMap = {};
for (const comp of results) {
  const seenInThisCompetitor = new Set();
  for (const e of comp.entities) {
    const key = e.normalizedName;
    if (!key || seenInThisCompetitor.has(key)) continue;
    seenInThisCompetitor.add(key);
    if (!entityMap[key]) {
      entityMap[key] = { name: e.name, type: e.type, competitorCount: 0, competitors: [], prominenceSamples: [] };
    }
    entityMap[key].competitorCount += 1;
    entityMap[key].competitors.push(comp.competitorName);
    entityMap[key].prominenceSamples.push(e.prominence);
  }
}

const competitorEntityTable = Object.values(entityMap).sort((a, b) => b.competitorCount - a.competitorCount);

return [{
  json: {
    ...state,
    competitorEntityTable,
    competitorsAnalyzedCount: results.length
  }
}];

const state = $input.first().json;
const yourEntityNames = new Set((state.yourEntities || []).map(e => e.normalizedName));

const missingEntities = (state.competitorEntityTable || [])
  .filter(e => e.competitorCount >= state.minCompetitorMentionsForGap && !yourEntityNames.has((e.name || '').trim().toLowerCase()))
  .map(e => ({ name: e.name, type: e.type, competitorCount: e.competitorCount, competitors: [...new Set(e.competitors)] }));

const yourEntityByName = {};
for (const e of (state.yourEntities || [])) yourEntityByName[e.normalizedName] = e;

const prominenceRank = { mentioned_briefly: 0, discussed: 1, dedicated_section: 2 };
function averageProminence(samples) {
  const vals = samples.map(s => prominenceRank[s] ?? 0);
  return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 0;
}

const weaklyCoveredEntities = (state.competitorEntityTable || [])
  .filter(e => e.competitorCount >= state.minCompetitorMentionsForGap && yourEntityByName[(e.name || '').trim().toLowerCase()])
  .map(e => {
    const yours = yourEntityByName[(e.name || '').trim().toLowerCase()];
    const competitorAvg = averageProminence(e.prominenceSamples);
    const yourLevel = prominenceRank[yours.prominence] ?? 0;
    return { name: e.name, type: e.type, yourProminence: yours.prominence, competitorAverageProminence: Math.round(competitorAvg * 100) / 100, gapSeverity: competitorAvg - yourLevel };
  })
  .filter(e => e.gapSeverity >= 1)
  .sort((a, b) => b.gapSeverity - a.gapSeverity);

return [{
  json: {
    ...state,
    missingEntities,
    weaklyCoveredEntities
  }
}];

const aiResponse = $input.first().json;
const state = $('Calculate Entity Gap').first().json;

let gapAnalysis;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  gapAnalysis = JSON.parse(cleaned);
} catch (e) {
  gapAnalysis = { topGaps: [], thematicClusters: [], overallSummary: 'Unable to parse AI response' };
}

const significantGap = (gapAnalysis.topGaps || []).length >= (state.significantGapCountThreshold || 5);

const topicReport = {
  topic: state.currentTopic,
  competitorsAnalyzed: state.competitorsAnalyzedCount,
  yourEntityCount: (state.yourEntities || []).length,
  missingEntityCount: (state.missingEntities || []).length,
  weaklyCoveredEntityCount: (state.weaklyCoveredEntities || []).length,
  missingEntities: state.missingEntities,
  weaklyCoveredEntities: state.weaklyCoveredEntities,
  gapAnalysis,
  significantGap
};

return [{
  json: {
    ...state,
    gapAnalysis,
    significantGap,
    results: [...(state.results || []), topicReport],
    processedTopicCount: (state.processedTopicCount || 0) + 1
  }
}];

