const item = $input.first().json;
const results = item.results || [];

const topicsWithSignificantGap = results.filter(r => r.significantGap).length;
const totalMissingEntities = results.reduce((s, r) => s + (r.missingEntityCount || 0), 0);

return [{
  json: {
    whatsappBusinessPhoneId: item.whatsappBusinessPhoneId,
    whatsappRecipientPhone: item.whatsappRecipientPhone,
    topicsChecked: results.length,
    topicsWithSignificantGap,
    totalMissingEntities,
    topicReports: results
  }
}];
